// Better HTTP: prefer cURL for HTTP(S), then preserve SMF's native
// fsockopen() path as the fallback if cURL is unavailable or fails.
require_once($sourcedir . '/BetterHttp.php');
$better_http_data = BetterHttp_FetchCurlFirst($url, $post_data, $redirection_level);
if ($better_http_data !== null)
	return $better_http_data;
